import subprocess, os, shutil, json
EXE="/workspace/executable"
ROOT="/tmp/ntests"
def run(args, cwd): return subprocess.run([EXE]+args, cwd=cwd, capture_output=True, text=True)
def setup(name, files):
    base=os.path.join(ROOT,name); shutil.rmtree(base, ignore_errors=True); os.makedirs(base)
    if isinstance(files, dict):
        items=files.items()
    else:
        items=[(f,"c-"+f) for f in files]
    for f,content in items:
        if f.endswith("/"): os.makedirs(os.path.join(base,f), exist_ok=True)
        else:
            p=os.path.join(base,f); os.makedirs(os.path.dirname(p), exist_ok=True); open(p,'w').write(content)
    return base
def snapshot(base):
    out=[]
    for root,dirs,fs in os.walk(base):
        dirs.sort()
        for d in sorted(dirs): out.append(os.path.relpath(os.path.join(root,d),base)+"/")
        for fn in sorted(fs):
            p=os.path.join(root,fn); out.append(os.path.relpath(p,base)+"="+open(p, errors='ignore').read())
    return sorted(out)
def show(name, files, args, extra=None):
    base=setup(name, files); 
    if extra: extra(base)
    p=run(args, cwd=base)
    rows=[l for l in p.stdout.splitlines()]
    print(f"### {name} args={args} exit={p.returncode}")
    if p.stdout: print("OUT:\n"+p.stdout, end='')
    if p.stderr: print("ERR:"+p.stderr, end='')
    print("FS:", snapshot(base))
    print()
PY
