{"command":"mkdir -p /workspace/src && cat > /workspace/src/main.rs << 'RS'
use clap::builder::PossibleValue;
use clap::{Arg, ArgAction, Command, ValueEnum};
use regex::{Captures, Regex};
use std::cmp::Ordering;
use std::collections::{BTreeMap, HashMap};
use std::env;
use std::error::Error;
use std::fmt;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;
use unicode_width::UnicodeWidthChar;
use walkdir::WalkDir;

// ---------------------------------------------------------------------------
// Sorting order

#[derive(Clone, Debug, PartialEq, Eq)]
enum SortOrder {
    Asc,
    Desc,
}

impl ValueEnum for SortOrder {
    fn value_variants<'a>() -> &'a [Self] {
        &[SortOrder::Asc, SortOrder::Desc]
    }

    fn to_possible_value(&self) -> Option<PossibleValue> {
        match self {
            SortOrder::Asc => Some(PossibleValue::new("asc").help("Sort in ascending order")),
            SortOrder::Desc => Some(PossibleValue::new("desc").help("Sort in descending order")),
        }
    }

    fn from_str(input: &str, ignore_case: bool) -> Result<Self, String> {
        if ignore_case {
            if input.eq_ignore_ascii_case("asc") {
                return Ok(SortOrder::Asc);
            }
            if input.eq_ignore_ascii_case("desc") {
                return Ok(SortOrder::Desc);
            }
        } else {
            if input == "asc" {
                return Ok(SortOrder::Asc);
            }
            if input == "desc" {
                return Ok(SortOrder::Desc);
            }
        }
        Err(format!("invalid variant: {}", input))
    }
}

// ---------------------------------------------------------------------------
// Errors

#[derive(Debug)]
struct MessageError(String);

impl fmt::Display for MessageError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}
impl Error for MessageError {}

#[derive(Debug)]
enum OutputFormatError {
    MustBeSet,
    Unclosed,
    Unopened,
    InvalidPadding(String),
    InvalidEscape(char, usize),
}

impl fmt::Display for OutputFormatError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            OutputFormatError::MustBeSet => {
                write!(f, "[output-format] output formatter must be set")
            }
            OutputFormatError::Unclosed => {
                write!(f, "[output-format] all opened placeholders must be closed by '}}'")
            }
            OutputFormatError::Unopened => {
                write!(
                    f,
                    "[output-format] an unopened placeholder could not be closed by '}}'"
                )
            }
            OutputFormatError::InvalidPadding(s) => {
                write!(f, "[output-format] unable to parse padding of '{}'", s)
            }
            OutputFormatError::InvalidEscape(c, idx) => {
                write!(
                    f,
                    "[output-format] invalid escape character of '{}' at '{}'",
                    c, idx
                )
            }
        }
    }
}
impl Error for OutputFormatError {}

type BoxError = Box<dyn Error>;

// ---------------------------------------------------------------------------
// Output format (placeholders)

#[derive(Debug, Clone)]
enum Segment {
    Text(String),
    Placeholder { group: String, padding: Option<usize> },
}

#[derive(Debug, Clone)]
struct OutputFormat {
    segments: Vec<Segment>,
}

impl OutputFormat {
    fn parse(input: &str) -> Result<Self, OutputFormatError> {
        let mut segments: Vec<Segment> = Vec::new();
        let mut text = String::new();
        let mut placeholder = String::new();
        let mut in_placeholder = false;

        let chars: Vec<char> = input.chars().collect();
        let mut i = 0usize; // index into chars; also the character index
        while i < chars.len() {
            let c = chars[i];
            if c == '\\' {
                if i + 1 < chars.len() {
                    let next = chars[i + 1];
                    if next == '{' || next == '}' || next == '\\' {
                        if in_placeholder {
                            placeholder.push(next);
                        } else {
                            text.push(next);
                        }
                        i += 2;
                        continue;
                    } else {
                        return Err(OutputFormatError::InvalidEscape(next, i + 1));
                    }
                } else {
                    // Trailing backslash: dropped.
                    i += 1;
                    continue;
                }
            }
            if !in_placeholder {
                if c == '{' {
                    in_placeholder = true;
                    placeholder.clear();
                } else if c == '}' {
                    return Err(OutputFormatError::Unopened);
                } else {
                    text.push(c);
                }
            } else {
                if c == '}' {
                    // Close placeholder.
                    if !text.is_empty() {
                        segments.push(Segment::Text(std::mem::take(&mut text)));
                    }
                    let content = std::mem::take(&mut placeholder);
                    let (group, padding) = if let Some((g, p)) = content.split_once(':') {
                        if p.is_empty() {
                            (g.to_string(), None)
                        } else {
                            match p.parse::<usize>() {
                                Ok(v) => (g.to_string(), Some(v)),
                                Err(_) => {
                                    return Err(OutputFormatError::InvalidPadding(
                                        p.to_string(),
                                    ))
                                }
                            }
                        }
                    } else {
                        (content, None)
                    };
                    segments.push(Segment::Placeholder { group, padding });
                    in_placeholder = false;
                } else {
                    placeholder.push(c);
                }
            }
            i += 1;
        }
        if in_placeholder {
            return Err(OutputFormatError::Unclosed);
        }
        if !text.is_empty() {
            segments.push(Segment::Text(text));
        }
        Ok(OutputFormat { segments })
    }

    fn from_option(input: &Option<String>) -> Result<Self, OutputFormatError> {
        match input {
            None => Err(OutputFormatError::MustBeSet),
            Some(s) => Self::parse(s),
        }
    }

    fn format(&self, groups: &[String], named: &HashMap<String, String>) -> String {
        let mut out = String::new();
        let mut auto_index: usize = 1;
        for seg in &self.segments {
            match seg {
                Segment::Text(t) => out.push_str(t),
                Segment::Placeholder { group, padding } => {
                    let value: String = if group.is_empty() {
                        let v = groups.get(auto_index).cloned().unwrap_or_default();
                        auto_index += 1;
                        v
                    } else if let Ok(idx) = group.parse::<usize>() {
                        groups.get(idx).cloned().unwrap_or_default()
                    } else {
                        named.get(group).cloned().unwrap_or_default()
                    };
                    if let Some(pad) = padding {
                        if let Ok(num) = value.parse::<u64>() {
                            out.push_str(&format!("{:0width$}", num, width = *pad));
                        } else {
                            out.push_str(&value);
                        }
                    } else {
                        out.push_str(&value);
                    }
                }
            }
        }
        out
    }
}

// ---------------------------------------------------------------------------
// Natural ordering

fn natural_compare(a: &str, b: &str) -> Ordering {
    let a_chars: Vec<char> = a.chars().collect();
    let b_chars: Vec<char> = b.chars().collect();
    let mut i = 0usize;
    let mut j = 0usize;
    loop {
        while i < a_chars.len() && a_chars[i].is_whitespace() {
            i += 1;
        }
        while j < b_chars.len() && b_chars[j].is_whitespace() {
            j += 1;
        }
        if i >= a_chars.len() && j >= b_chars.len() {
            return Ordering::Equal;
        }
        if i >= a_chars.len() {
            return Ordering::Less;
        }
        if j >= b_chars.len() {
            return Ordering::Greater;
        }
        let ca = a_chars[i];
        let cb = b_chars[j];
        if ca.is_ascii_digit() && cb.is_ascii_digit() {
            let start_a = i;
            let start_b = j;
            while i < a_chars.len() && a_chars[i].is_ascii_digit() {
                i += 1;
            }
            while j < b_chars.len() && b_chars[j].is_ascii_digit() {
                j += 1;
            }
            let run_a = &a_chars[start_a..i];
            let run_b = &b_chars[start_b..j];
            if run_a[0] == '0' || run_b[0] == '0' {
                // Fractional (left-aligned) comparison.
                let mut k = 0usize;
                loop {
                    if k >= run_a.len() && k >= run_b.len() {
                        break;
                    }
                    if k >= run_a.len() {
                        return Ordering::Less;
                    }
                    if k >= run_b.len() {
                        return Ordering::Greater;
                    }
                    if run_a[k] != run_b[k] {
                        return run_a[k].cmp(&run_b[k]);
                    }
                    k += 1;
                }
                // Equal digit runs; continue with following characters.
                continue;
            } else {
                if run_a.len() != run_b.len() {
                    return run_a.len().cmp(&run_b.len());
                }
                for k in 0..run_a.len() {
                    if run_a[k] != run_b[k] {
                        return run_a[k].cmp(&run_b[k]);
                    }
                }
                continue;
            }
        }
        if ca != cb {
            return ca.cmp(&cb);
        }
        i += 1;
        j += 1;
    }
}

// ---------------------------------------------------------------------------
// CLI

fn build_cli() -> Command {
    Command::new("nomino")
        .version(env!("CARGO_PKG_VERSION"))
        .about("Batch rename utility for developers")
        .after_help("OUTPUT pattern accepts placeholders that have the format of '{G:P}' where 'G' is the captured group and 'P' is the padding of digits with `0`. Please refer to https://github.com/yaa110/nomino for more information.")
        .arg(
            Arg::new("inputs")
                .value_name("[SOURCE] OUTPUT")
                .help("OUTPUT is the pattern to be used for renaming files, and SOURCE is the optional regex pattern to match by filenames. SOURCE has the same function as -r option")
                .action(ArgAction::Append)
                .num_args(0..),
        )
        .arg(
            Arg::new("dir")
                .short('d')
                .long("dir")
                .value_name("PATH")
                .help("Sets the working directory")
                .value_parser(clap::value_parser!(PathBuf))
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("depth")
                .long("depth")
                .value_name("DEPTH")
                .help("Optional value to overwrite inferred subdirectory depth value in 'regex' mode")
                .value_parser(clap::value_parser!(usize))
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("no-extension")
                .short('E')
                .long("no-extension")
                .help("Does not preserve the extension of input files in 'sort' and 'regex' options")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("generate")
                .short('g')
                .long("generate")
                .value_name("PATH")
                .help("Stores a JSON map file in '<PATH>' after renaming files")
                .value_parser(clap::value_parser!(PathBuf))
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("mkdir")
                .short('k')
                .long("mkdir")
                .help("Recursively creates all parent directories of '<OUTPUT>' if they are missing")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("map")
                .short('m')
                .long("map")
                .visible_alias("from-file")
                .value_name("PATH")
                .help("Sets the path of map file to be used for renaming files")
                .value_parser(clap::value_parser!(PathBuf))
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("max-depth")
                .long("max-depth")
                .value_name("DEPTH")
                .help("Optional value to set the maximum of subdirectory depth value in 'regex' mode")
                .value_parser(clap::value_parser!(usize))
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("quiet")
                .short('q')
                .long("quiet")
                .help("Does not print the map table to stdout")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("regex")
                .short('r')
                .long("regex")
                .value_name("PATTERN")
                .help("Regex pattern to match by filenames")
                .action(ArgAction::Set)
                .requires("inputs"),
        )
        .arg(
            Arg::new("sort")
                .short('s')
                .long("sort")
                .value_name("ORDER")
                .help("Sets the order of natural sorting (by name) to rename files using enumerator")
                .value_parser(clap::builder::EnumValueParser::<SortOrder>::new())
                .ignore_case(true)
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("test")
                .short('t')
                .long("test")
                .visible_alias("dry-run")
                .help("Runs in test mode without renaming actual files")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("overwrite")
                .short('w')
                .long("overwrite")
                .help("Overwrites output files, otherwise, a '_' is prepended to filename")
                .action(ArgAction::SetTrue),
        )
}

// ---------------------------------------------------------------------------
// Table rendering

fn display_width(s: &str) -> usize {
    let mut width = 0usize;
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\u{1b}' {
            // Treat an ANSI CSI sequence as width 1 (per the ESC character).
            if chars.peek() == Some(&'[') {
                chars.next();
                for n in chars.by_ref() {
                    if ('\u{40}'..='\u{7e}').contains(&n) {
                        break;
                    }
                }
            }
            width += 1;
            continue;
        }
        width += UnicodeWidthChar::width(c).unwrap_or(1);
    }
    width
}

fn cell_lines(s: &str) -> Vec<String> {
    let lines: Vec<String> = s.lines().map(|l| l.to_string()).collect();
    if lines.is_empty() {
        vec![String::new()]
    } else {
        lines
    }
}

fn print_table(map: &BTreeMap<String, String>) {
    // map: output -> input
    let rows: Vec<(String, String)> = map.iter().map(|(o, i)| (i.clone(), o.clone())).collect();
    let headers = ("Input".to_string(), "Output".to_string());
    let mut width_in = display_width(&headers.0);
    let mut width_out = display_width(&headers.1);
    let mut all_cells: Vec<(Vec<String>, Vec<String>)> = Vec::new();
    for (inp, out) in &rows {
        let li = cell_lines(inp);
        let lo = cell_lines(out);
        for l in &li {
            width_in = width_in.max(display_width(l));
        }
        for l in &lo {
            width_out = width_out.max(display_width(l));
        }
        all_cells.push((li, lo));
    }
    let border = format!(
        "+{}+{}+",
        "-".repeat(width_in + 2),
        "-".repeat(width_out + 2)
    );
    let print_row = |left_lines: &[String], right_lines: &[String]| {
        let height = left_lines.len().max(right_lines.len()).max(1);
        for idx in 0..height {
            let l = left_lines.get(idx).map(|s| s.as_str()).unwrap_or("");
            let r = right_lines.get(idx).map(|s| s.as_str()).unwrap_or("");
            let lw = display_width(l);
            let rw = display_width(r);
            println!(
                "| {}{} | {}{} |",
                l,
                " ".repeat(width_in - lw),
                r,
                " ".repeat(width_out - rw)
            );
        }
    };
    println!("{}", border);
    print_row(
        &vec![headers.0.clone()],
        &vec![headers.1.clone()],
    );
    println!("{}", border);
    for (li, lo) in &all_cells {
        print_row(li, lo);
    }
    println!("{}", border);
}

// ---------------------------------------------------------------------------
// Rename helper

struct Options {
    mkdir: bool,
    test: bool,
    overwrite: bool,
    no_extension: bool,
    quiet: bool,
}

fn rename_one(
    input: &str,
    output_path_in: PathBuf,
    opts: &Options,
    result: &mut BTreeMap<String, String>,
    had_error: &mut bool,
) {
    let mut output = output_path_in;
    if opts.mkdir {
        if let Some(parent) = output.parent() {
            let _ = fs::create_dir_all(parent);
        }
    }
    if !opts.overwrite {
        let input_path = Path::new(input);
        while output.exists() && output.as_path() != input_path {
            let fname = output
                .file_name()
                .map(|s| s.to_string_lossy().into_owned())
                .unwrap_or_default();
            let before = output.clone();
            output.set_file_name(format!("_{}", fname));
            if output == before {
                // Should not happen, but avoid an infinite loop.
                break;
            }
        }
    }
    if !opts.test {
        if let Err(e) = fs::rename(input, &output) {
            eprintln!("[error] unable to rename '{}': {}", input, e);
            *had_error = true;
            return;
        }
    }
    result.insert(output.display().to_string(), input.to_string());
}

fn with_extension(formatted: String, input: &str, no_extension: bool) -> PathBuf {
    if no_extension {
        return PathBuf::from(formatted);
    }
    let ext = Path::new(input).extension();
    match ext {
        Some(e) => PathBuf::from(format!("{}.{}", formatted, e.to_string_lossy())),
        None => PathBuf::from(formatted),
    }
}

// ---------------------------------------------------------------------------
// Modes

fn run_regex(
    pattern: &str,
    output_opt: &Option<String>,
    opts: &Options,
    depth_opt: Option<usize>,
    max_depth_opt: Option<usize>,
) -> Result<(BTreeMap<String, String>, bool), BoxError> {
    let re = Regex::new(pattern)?;
    let formatter = OutputFormat::from_option(output_opt)?;
    let inferred = pattern.matches('/').count() + 1;
    let specified = depth_opt.unwrap_or(inferred);
    let max_effective = max_depth_opt.unwrap_or(specified);
    let min_effective = specified.min(max_effective);

    let mut result: BTreeMap<String, String> = BTreeMap::new();
    let mut had_error = false;

    let walker = WalkDir::new(".")
        .min_depth(min_effective)
        .max_depth(max_effective)
        .into_iter();
    for entry in walker {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let path = entry.path();
        let rel = match path.strip_prefix(".") {
            Ok(p) => p.to_path_buf(),
            Err(_) => path.to_path_buf(),
        };
        let rel_str = match rel.to_str() {
            Some(s) => s.to_string(),
            None => continue,
        };
        let caps: Captures = match re.captures(&rel_str) {
            Some(c) => c,
            None => continue,
        };
        let groups: Vec<String> = caps
            .iter()
            .map(|m| m.map(|x| x.as_str().to_string()).unwrap_or_default())
            .collect();
        let mut named: HashMap<String, String> = HashMap::new();
        for name in re.capture_names().flatten() {
            let v = caps
                .name(name)
                .map(|m| m.as_str().to_string())
                .unwrap_or_default();
            named.insert(name.to_string(), v);
        }
        let formatted = formatter.format(&groups, &named);
        let output = with_extension(formatted, &rel_str, opts.no_extension);
        rename_one(&rel_str, output, opts, &mut result, &mut had_error);
    }
    Ok((result, had_error))
}

fn run_sort(
    order: &SortOrder,
    output_opt: &Option<String>,
    opts: &Options,
) -> Result<(BTreeMap<String, String>, bool), BoxError> {
    let formatter = OutputFormat::from_option(output_opt)?;
    let mut names: Vec<String> = Vec::new();
    let read = fs::read_dir(".")?;
    for entry in read {
        if let Ok(e) = entry {
            names.push(e.file_name().to_string_lossy().into_owned());
        }
    }
    match order {
        SortOrder::Asc => names.sort_by(|a, b| natural_compare(a, b)),
        SortOrder::Desc => names.sort_by(|a, b| natural_compare(b, a)),
    }
    let mut result: BTreeMap<String, String> = BTreeMap::new();
    let mut had_error = false;
    let named: HashMap<String, String> = HashMap::new();
    for (idx, name) in names.iter().enumerate() {
        let groups = vec![name.clone(), (idx + 1).to_string()];
        let formatted = formatter.format(&groups, &named);
        let output = with_extension(formatted, name, opts.no_extension);
        rename_one(name, output, opts, &mut result, &mut had_error);
    }
    Ok((result, had_error))
}

fn run_map(
    map_path: &Path,
    output_opt: &Option<String>,
    opts: &Options,
) -> Result<(BTreeMap<String, String>, bool), BoxError> {
    let file = fs::File::open(map_path)?;
    let input_map: HashMap<String, String> = serde_json::from_reader(file)?;
    // The output formatter is parsed even in map mode (if supplied), although
    // it is not used for renaming in this mode.
    if let Some(out_str) = output_opt {
        let _ = OutputFormat::parse(out_str)?;
    }
    let mut result: BTreeMap<String, String> = BTreeMap::new();
    let mut had_error = false;
    for (input, output) in &input_map {
        rename_one(
            input,
            PathBuf::from(output),
            opts,
            &mut result,
            &mut had_error,
        );
    }
    Ok((result, had_error))
}

// ---------------------------------------------------------------------------

fn real_main() -> Result<i32, BoxError> {
    let matches = build_cli().get_matches();

    if let Some(dir) = matches.get_one::<PathBuf>("dir") {
        env::set_current_dir(dir)?;
    }

    let inputs: Vec<String> = matches
        .get_many::<String>("inputs")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let mut inputs_iter = inputs.clone();
    let output_opt = inputs_iter.pop();
    let source_opt = inputs_iter.pop();

    let regex_opt: Option<String> = matches.get_one::<String>("regex").cloned();
    let sort_opt: Option<SortOrder> = matches.get_one::<SortOrder>("sort").cloned();
    let map_opt: Option<PathBuf> = matches.get_one::<PathBuf>("map").cloned();

    if source_opt.is_some() && (regex_opt.is_some() || sort_opt.is_some() || map_opt.is_some()) {
        return Err(Box::new(MessageError(
            "optional SOURCE must be used without setting regex, map or sort flags".to_string(),
        )));
    }

    let opts = Options {
        mkdir: matches.get_flag("mkdir"),
        test: matches.get_flag("test"),
        overwrite: matches.get_flag("overwrite"),
        no_extension: matches.get_flag("no-extension"),
        quiet: matches.get_flag("quiet"),
    };
    let generate_opt: Option<PathBuf> = matches.get_one::<PathBuf>("generate").cloned();
    let depth_opt: Option<usize> = matches.get_one::<usize>("depth").copied();
    let max_depth_opt: Option<usize> = matches.get_one::<usize>("max-depth").copied();

    let (result, had_error): (BTreeMap<String, String>, bool) =
        if let Some(pattern) = &regex_opt {
            run_regex(pattern, &output_opt, &opts, depth_opt, max_depth_opt)?
        } else if let Some(order) = &sort_opt {
            run_sort(order, &output_opt, &opts)?
        } else if let Some(map_path) = &map_opt {
            run_map(map_path, &output_opt, &opts)?
        } else if let Some(source) = &source_opt {
            run_regex(source, &output_opt, &opts, depth_opt, max_depth_opt)?
        } else {
            let prog = env::args().next().unwrap_or_default();
            return Err(Box::new(MessageError(format!(
                "one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.\nusage: run '{} --help' for more information.",
                prog
            ))));
        };

    if let Some(gen_path) = &generate_opt {
        let json = serde_json::to_string_pretty(&result)?;
        fs::write(gen_path, json)?;
    }

    if !opts.quiet && !result.is_empty() {
        print_table(&result);
    }

    Ok(if had_error { 1 } else { 0 })
}

fn main() -> ExitCode {
    match real_main() {
        Ok(code) => ExitCode::from(code as u8),
        Err(e) => {
            eprintln!("error: {}", e);
            ExitCode::from(1)
        }
    }
}
RS"}

