use clap::builder::PossibleValue;
use clap::{Arg, ArgAction, Command, ValueEnum};
use regex::{Captures, Regex};
use std::cmp::Ordering;
use std::collections::{BTreeMap, HashMap};
use std::env;
use std::error::Error;
use std::fmt;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;
use unicode_width::UnicodeWidthChar;
use walkdir::WalkDir;

// ---------------------------------------------------------------------------
// Sorting order

#[derive(Clone, Debug, PartialEq, Eq)]
enum SortOrder {
    Asc,
    Desc,
}

impl ValueEnum for SortOrder {
    fn value_variants<'a>() -> &'a [Self] {
        &[SortOrder::Asc, SortOrder::Desc]
    }

    fn to_possible_value(&self) -> Option<PossibleValue> {
        match self {
            SortOrder::Asc => Some(PossibleValue::new("asc").help("Sort in ascending order")),
            SortOrder::Desc => Some(PossibleValue::new("desc").help("Sort in descending order")),
        }
    }

    fn from_str(input: &str, ignore_case: bool) -> Result<Self, String> {
        if ignore_case {
            if input.eq_ignore_ascii_case("asc") {
                return Ok(SortOrder::Asc);
            }
            if input.eq_ignore_ascii_case("desc") {
                return Ok(SortOrder::Desc);
            }
        } else {
            if input == "asc" {
                return Ok(SortOrder::Asc);
            }
            if input == "desc" {
                return Ok(SortOrder::Desc);
            }
        }
        Err(format!("invalid variant: {}", input))
    }
}

// ---------------------------------------------------------------------------
// Errors

#[derive(Debug)]
struct MessageError(String);

impl fmt::Display for MessageError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}
impl Error for MessageError {}

#[derive(Debug)]
enum OutputFormatError {
    MustBeSet,
    Unclosed,
    Unopened,
    InvalidPadding(String),
    InvalidEscape(char, usize),
}

impl fmt::Display for OutputFormatError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            OutputFormatError::MustBeSet => {
                write!(f, "[output-format] output formatter must be set")
            }
            OutputFormatError::Unclosed => {
                write!(f, "[output-format] all opened placeholders must be closed by '}}'")
            }
            OutputFormatError::Unopened => {
                write!(
                    f,
                    "[output-format] an unopened placeholder could not be closed by '}}'"
                )
            }
            OutputFormatError::InvalidPadding(s) => {
                write!(f, "[output-format] unable to parse padding of '{}'", s)
            }
            OutputFormatError::InvalidEscape(c, idx) => {
                write!(
                    f,
                    "[output-format] invalid escape character of '{}' at '{}'",
                    c, idx
                )
            }
        }
    }
}
impl Error for OutputFormatError {}

type BoxError = Box<dyn Error>;

// ---------------------------------------------------------------------------
// Output format (placeholders)

#[derive(Debug, Clone)]
enum Segment {
    Text(String),
    Placeholder { group: String, padding: Option<usize> },
}

#[derive(Debug, Clone)]
struct OutputFormat {
    segments: Vec<Segment>,
}

impl OutputFormat {
    fn parse(input: &str) -> Result<Self, OutputFormatError> {
        let mut segments: Vec<Segment> = Vec::new();
        let mut text = String::new();
        let mut placeholder = String::new();
        let mut in_placeholder = false;

        let chars: Vec<char> = input.chars().collect();
        let mut i = 0usize; // index into chars; also the character index
        while i < chars.len() {
            let c = chars[i];
            if c == '\\' {
                if i + 1 < chars.len() {
                    let next = chars[i + 1];
                    if next == '{' || next == '}' || next == '\\' {
                        if in_placeholder {
                            placeholder.push(next);
                        } else {
                            text.push(next);
                        }
                        i += 2;
                        continue;
                    } else {
                        return Err(OutputFormatError::InvalidEscape(next, i + 1));
                    }
                } else {
                    // Trailing backslash: dropped.
                    i += 1;
                    continue;
                }
            }
            if !in_placeholder {
                if c == '{' {
                    in_placeholder = true;
                    placeholder.clear();
                } else if c == '}' {
                    return Err(OutputFormatError::Unopened);
                } else {
                    text.push(c);
                }
            } else {
                if c == '}' {
                    // Close placeholder.
                    if !text.is_empty() {
                        segments.push(Segment::Text(std::mem::take(&mut text)));
                    }
                    let content = std::mem::take(&mut placeholder);
                    let (group, padding) = if let Some((g, p)) = content.split_once(':') {
                        if p.is_empty() {
                            (g.to_string(), None)
                        } else {
                            match p.parse::<usize>() {
                                Ok(v) => (g.to_string(), Some(v)),
                                Err(_) => {
                                    return Err(OutputFormatError::InvalidPadding(
                                        p.to_string(),
                                    ))
                                }
                            }
                        }
                    } else {
                        (content, None)
                    };
                    segments.push(Segment::Placeholder { group, padding });
                    in_placeholder = false;
                } else {
                    placeholder.push(c);
                }
            }
            i += 1;
        }
        if in_placeholder {
            return Err(OutputFormatError::Unclosed);
        }
        if !text.is_empty() {
            segments.push(Segment::Text(text));
        }
        Ok(OutputFormat { segments })
    }

    fn from_option(input: &Option<String>) -> Result<Self, OutputFormatError> {
        match input {
            None => Err(OutputFormatError::MustBeSet),
            Some(s) => Self::parse(s),
        }
    }

    fn format(&self, groups: &[String], named: &HashMap<String, String>) -> String {
        let mut out = String::new();
        let mut auto_index: usize = 1;
        for seg in &self.segments {
            match seg {
                Segment::Text(t) => out.push_str(t),
                Segment::Placeholder { group, padding } => {
                    let value: String = if group.is_empty() {
                        let v = groups.get(auto_index).cloned().unwrap_or_default();
                        auto_index += 1;
                        v
                    } else if let Ok(idx) = group.parse::<usize>() {
                        groups.get(idx).cloned().unwrap_or_default()
                    } else {
                        named.get(group).cloned().unwrap_or_default()
                    };
                    if let Some(pad) = padding {
                        if let Ok(num) = value.parse::<u64>() {
                            out.push_str(&format!("{:0width$}", num, width = *pad));
                        } else {
                            out.push_str(&value);
                        }
                    } else {
                        out.push_str(&value);
                    }
                }
            }
        }
        out
    }
}

// ---------------------------------------------------------------------------
// Natural ordering

fn natural_compare(a: &str, b: &str) -> Ordering {
    let a_chars: Vec<char> = a.chars().collect();
    let b_chars: Vec<char> = b.chars().collect();
    let mut i = 0usize;
    let mut j = 0usize;
    loop {
        while i < a_chars.len() && a_chars[i].is_whitespace() {
            i += 1;
        }
        while j < b_chars.len() && b_chars[j].is_whitespace() {
            j += 1;
        }
        if i >= a_chars.len() && j >= b_chars.len() {
            return Ordering::Equal;
        }
        if i >= a_chars.len() {
            return Ordering::Less;
        }
        if j >= b_chars.len() {
            return Ordering::Greater;
        }
        let ca = a_chars[i];
        let cb = b_chars[j];
        if ca.is_ascii_digit() && cb.is_ascii_digit() {
            let start_a = i;
            let start_b = j;
            while i < a_chars.len() && a_chars[i].is_ascii_digit() {
                i += 1;
            }
            while j < b_chars.len() && b_chars[j].is_ascii_digit() {
                j += 1;
            }
            let run_a = &a_chars[start_a..i];
            let run_b = &b_chars[start_b..j];
            if run_a[0] == '0' || run_b[0] == '0' {
                // Fractional (left-aligned) comparison.
                let mut k = 0usize;
                loop {
                    if k >= run_a.len() && k >= run_b.len() {
                        break;
                    }
                    if k >= run_a.len() {
                        return Ordering::Less;
                    }
                    if k >= run_b.len() {
                        return Ordering::Greater;
                    }
                    if run_a[k] != run_b[k] {
                        return run_a[k].cmp(&run_b[k]);
                    }
                    k += 1;
                }
                // Equal digit runs; continue with following characters.
                continue;
            } else {
                if run_a.len() != run_b.len() {
                    return run_a.len().cmp(&run_b.len());
                }
                for k in 0..run_a.len() {
                    if run_a[k] != run_b[k] {
                        return run_a[k].cmp(&run_b[k]);
                    }
                }
                continue;
            }
        }
        if ca != cb {
            return ca.cmp(&cb);
        }
        i += 1;
        j += 1;
    }
}

// ---------------------------------------------------------------------------
// CLI

fn build_cli() -> Command {
    Command::new("nomino")
        .version(env!("CARGO_PKG_VERSION"))
        .about("Batch rename utility for developers")
        .after_help("OUTPUT pattern accepts placeholders that have the format of '{G:P}' where 'G' is the captured group and 'P' is the padding of digits with `0`. Please refer to https://github.com/yaa110/nomino for more information.")
        .arg(
            Arg::new("inputs")
                .value_name("[SOURCE] OUTPUT")
                .help("OUTPUT is the pattern to be used for renaming files, and SOURCE is the optional regex pattern to match by filenames. SOURCE has the same function as -r option")
                .action(ArgAction::Append)
                .num_args(0..),
        )
        .arg(
            Arg::new("dir")
                .short('d')
                .long("dir")
                .value_name("PATH")
                .help("Sets the working directory")
                .value_parser(clap::value_parser!(PathBuf))
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("depth")
                .long("depth")
                .value_name("DEPTH")
                .help("Optional value to overwrite inferred subdirectory depth value in 'regex' mode")
                .value_parser(clap::value_parser!(usize))
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("no-extension")
                .short('E')
                .long("no-extension")
                .help("Does not preserve the extension of input files in 'sort' and 'regex' options")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("generate")
                .short('g')
                .long("generate")
                .value_name("PATH")
                .help("Stores a JSON map file in '<PATH>' after renaming files")
                .value_parser(clap::value_parser!(PathBuf))
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("mkdir")
                .short('k')
                .long("mkdir")
                .help("Recursively creates all parent directories of '<OUTPUT>' if they are missing")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("map")
                .short('m')
                .long("map")
                .visible_alias("from-file")
                .value_name("PATH")
                .help("Sets the path of map file to be used for renaming files")
                .value_parser(clap::value_parser!(PathBuf))
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("max-depth")
                .long("max-depth")
                .value_name("DEPTH")
                .help("Optional value to set the maximum of subdirectory depth value in 'regex' mode")
                .value_parser(clap::value_parser!(usize))
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("quiet")
                .short('q')
                .long("quiet")
                .help("Does not print the map table to stdout")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("regex")
                .short('r')
