// ---------------------------------------------------------------------------
// Table rendering

fn display_width(s: &str) -> usize {
    let mut width = 0usize;
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\u{1b}' {
            // Treat an ANSI CSI sequence as width 1 (per the ESC character).
            if chars.peek() == Some(&'[') {
                chars.next();
                for n in chars.by_ref() {
                    if ('\u{40}'..='\u{7e}').contains(&n) {
                        break;
                    }
                }
            }
            width += 1;
            continue;
        }
        width += UnicodeWidthChar::width(c).unwrap_or(1);
    }
    width
}

fn cell_lines(s: &str) -> Vec<String> {
    let lines: Vec<String> = s.lines().map(|l| l.to_string()).collect();
    if lines.is_empty() {
        vec![String::new()]
    } else {
        lines
    }
}

fn print_table(map: &BTreeMap<String, String>) {
    // map: output -> input
    let rows: Vec<(String, String)> = map.iter().map(|(o, i)| (i.clone(), o.clone())).collect();
    let headers = ("Input".to_string(), "Output".to_string());
    let mut width_in = display_width(&headers.0);
    let mut width_out = display_width(&headers.1);
    let mut all_cells: Vec<(Vec<String>, Vec<String>)> = Vec::new();
    for (inp, out) in &rows {
        let li = cell_lines(inp);
        let lo = cell_lines(out);
        for l in &li {
            width_in = width_in.max(display_width(l));
        }
        for l in &lo {
            width_out = width_out.max(display_width(l));
        }
        all_cells.push((li, lo));
    }
    let border = format!(
        "+{}+{}+",
        "-".repeat(width_in + 2),
        "-".repeat(width_out + 2)
    );
    let print_row = |left_lines: &[String], right_lines: &[String]| {
        let height = left_lines.len().max(right_lines.len()).max(1);
        for idx in 0..height {
            let l = left_lines.get(idx).map(|s| s.as_str()).unwrap_or("");
            let r = right_lines.get(idx).map(|s| s.as_str()).unwrap_or("");
            let lw = display_width(l);
            let rw = display_width(r);
            println!(
                "| {}{} | {}{} |",
                l,
                " ".repeat(width_in - lw),
                r,
                " ".repeat(width_out - rw)
            );
        }
    };
    println!("{}", border);
    print_row(
        &vec![headers.0.clone()],
        &vec![headers.1.clone()],
    );
    println!("{}", border);
    for (li, lo) in &all_cells {
        print_row(li, lo);
    }
    println!("{}", border);
}

// ---------------------------------------------------------------------------
// Rename helper

struct Options {
    mkdir: bool,
    test: bool,
    overwrite: bool,
    no_extension: bool,
    quiet: bool,
}

fn rename_one(
    input: &str,
    output_path_in: PathBuf,
    opts: &Options,
    result: &mut BTreeMap<String, String>,
    had_error: &mut bool,
) {
    let mut output = output_path_in;
    if opts.mkdir {
        if let Some(parent) = output.parent() {
            let _ = fs::create_dir_all(parent);
        }
    }
    if !opts.overwrite {
        let input_path = Path::new(input);
        while output.exists() && output.as_path() != input_path {
            let fname = output
                .file_name()
                .map(|s| s.to_string_lossy().into_owned())
                .unwrap_or_default();
            let before = output.clone();
            output.set_file_name(format!("_{}", fname));
            if output == before {
                // Should not happen, but avoid an infinite loop.
                break;
            }
        }
    }
    if !opts.test {
        if let Err(e) = fs::rename(input, &output) {
            eprintln!("[error] unable to rename '{}': {}", input, e);
            *had_error = true;
            return;
        }
    }
    result.insert(output.display().to_string(), input.to_string());
}

fn with_extension(formatted: String, input: &str, no_extension: bool) -> PathBuf {
    if no_extension {
        return PathBuf::from(formatted);
    }
    let ext = Path::new(input).extension();
    match ext {
        Some(e) => PathBuf::from(format!("{}.{}", formatted, e.to_string_lossy())),
        None => PathBuf::from(formatted),
    }
}

// ---------------------------------------------------------------------------
// Modes

fn run_regex(
    pattern: &str,
    output_opt: &Option<String>,
    opts: &Options,
    depth_opt: Option<usize>,
    max_depth_opt: Option<usize>,
) -> Result<(BTreeMap<String, String>, bool), BoxError> {
    let re = Regex::new(pattern)?;
    let formatter = OutputFormat::from_option(output_opt)?;
    let inferred = pattern.matches('/').count() + 1;
    let specified = depth_opt.unwrap_or(inferred);
    let max_effective = max_depth_opt.unwrap_or(specified);
    let min_effective = specified.min(max_effective);

    let mut result: BTreeMap<String, String> = BTreeMap::new();
    let mut had_error = false;

    let walker = WalkDir::new(".")
        .min_depth(min_effective)
        .max_depth(max_effective)
        .into_iter();
    for entry in walker {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let path = entry.path();
        let rel = match path.strip_prefix(".") {
            Ok(p) => p.to_path_buf(),
            Err(_) => path.to_path_buf(),
        };
        let rel_str = match rel.to_str() {
            Some(s) => s.to_string(),
            None => continue,
        };
        let caps: Captures = match re.captures(&rel_str) {
            Some(c) => c,
            None => continue,
        };
        let groups: Vec<String> = caps
            .iter()
            .map(|m| m.map(|x| x.as_str().to_string()).unwrap_or_default())
            .collect();
        let mut named: HashMap<String, String> = HashMap::new();
        for name in re.capture_names().flatten() {
            let v = caps
                .name(name)
                .map(|m| m.as_str().to_string())
                .unwrap_or_default();
            named.insert(name.to_string(), v);
        }
        let formatted = formatter.format(&groups, &named);
        let output = with_extension(formatted, &rel_str, opts.no_extension);
        rename_one(&rel_str, output, opts, &mut result, &mut had_error);
    }
    Ok((result, had_error))
}

fn run_sort(
    order: &SortOrder,
    output_opt: &Option<String>,
    opts: &Options,
) -> Result<(BTreeMap<String, String>, bool), BoxError> {
    let formatter = OutputFormat::from_option(output_opt)?;
    let mut names: Vec<String> = Vec::new();
    let read = fs::read_dir(".")?;
    for entry in read {
        if let Ok(e) = entry {
            names.push(e.file_name().to_string_lossy().into_owned());
        }
    }
    match order {
        SortOrder::Asc => names.sort_by(|a, b| natural_compare(a, b)),
        SortOrder::Desc => names.sort_by(|a, b| natural_compare(b, a)),
    }
    let mut result: BTreeMap<String, String> = BTreeMap::new();
    let mut had_error = false;
    let named: HashMap<String, String> = HashMap::new();
    for (idx, name) in names.iter().enumerate() {
        let groups = vec![name.clone(), (idx + 1).to_string()];
        let formatted = formatter.format(&groups, &named);
        let output = with_extension(formatted, name, opts.no_extension);
        rename_one(name, output, opts, &mut result, &mut had_error);
    }
    Ok((result, had_error))
}

fn run_map(
    map_path: &Path,
    output_opt: &Option<String>,
    opts: &Options,
) -> Result<(BTreeMap<String, String>, bool), BoxError> {
    let file = fs::File::open(map_path)?;
    let input_map: HashMap<String, String> = serde_json::from_reader(file)?;
    // The output formatter is parsed even in map mode (if supplied), although
    // it is not used for renaming in this mode.
    if let Some(out_str) = output_opt {
        let _ = OutputFormat::parse(out_str)?;
    }
    let mut result: BTreeMap<String, String> = BTreeMap::new();
    let mut had_error = false;
    for (input, output) in &input_map {
        rename_one(
            input,
            PathBuf::from(output),
            opts,
            &mut result,
            &mut had_error,
        );
    }
    Ok((result, had_error))
}

// ---------------------------------------------------------------------------

fn real_main() -> Result<i32, BoxError> {
    let matches = build_cli().get_matches();

    if let Some(dir) = matches.get_one::<PathBuf>("dir") {
        env::set_current_dir(dir)?;
    }

    let inputs: Vec<String> = matches
        .get_many::<String>("inputs")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let mut inputs_iter = inputs.clone();
    let output_opt = inputs_iter.pop();
    let source_opt = inputs_iter.pop();

    let regex_opt: Option<String> = matches.get_one::<String>("regex").cloned();
    let sort_opt: Option<SortOrder> = matches.get_one::<SortOrder>("sort").cloned();
    let map_opt: Option<PathBuf> = matches.get_one::<PathBuf>("map").cloned();

    if source_opt.is_some() && (regex_opt.is_some() || sort_opt.is_some() || map_opt.is_some()) {
        return Err(Box::new(MessageError(
            "optional SOURCE must be used without setting regex, map or sort flags".to_string(),
        )));
    }

    let opts = Options {
        mkdir: matches.get_flag("mkdir"),
        test: matches.get_flag("test"),
        overwrite: matches.get_flag("overwrite"),
        no_extension: matches.get_flag("no-extension"),
        quiet: matches.get_flag("quiet"),
    };
    let generate_opt: Option<PathBuf> = matches.get_one::<PathBuf>("generate").cloned();
    let depth_opt: Option<usize> = matches.get_one::<usize>("depth").copied();
    let max_depth_opt: Option<usize> = matches.get_one::<usize>("max-depth").copied();

    let (result, had_error): (BTreeMap<String, String>, bool) =
        if let Some(pattern) = &regex_opt {
            run_regex(pattern, &output_opt, &opts, depth_opt, max_depth_opt)?
        } else if let Some(order) = &sort_opt {
            run_sort(order, &output_opt, &opts)?
        } else if let Some(map_path) = &map_opt {
            run_map(map_path, &output_opt, &opts)?
        } else if let Some(source) = &source_opt {
            run_regex(source, &output_opt, &opts, depth_opt, max_depth_opt)?
        } else {
            let prog = env::args().next().unwrap_or_default();
            return Err(Box::new(MessageError(format!(
                "one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.\nusage: run '{} --help' for more information.",
                prog
            ))));
        };

    if let Some(gen_path) = &generate_opt {
        let json = serde_json::to_string_pretty(&result)?;
        fs::write(gen_path, json)?;
    }

    if !opts.quiet && !result.is_empty() {
        print_table(&result);
    }

    Ok(if had_error { 1 } else { 0 })
}

fn main() -> ExitCode {
    match real_main() {
        Ok(code) => ExitCode::from(code as u8),
        Err(e) => {
            eprintln!("error: {}", e);
            ExitCode::from(1)
        }
    }
}
